```java
@Transactional
public ReleaseResult release(List<String> keys, String actor) {
    if (keys == null || keys.isEmpty() || keys.size() > 50) throw badRequest;
    // dedupe? duplicate keys in batch — treat as 400? Let's reject duplicates as 400 to avoid double-release ambiguity.
    validate each key non-blank → 400
    sort keys for deterministic lock order
    List<ItemFailure> failures = new ArrayList<>();
    List<Measurement> toRelease = new ArrayList<>();
    for (key : sortedKeys) {
        Optional<Measurement> opt = repo.findByKeyForUpdate(key);
        if (empty) { failures.add(key, [MEASUREMENT_NOT_FOUND]); continue; }
        Measurement m = opt.get();
        List<String> reasons = new ArrayList<>();
        if (m.status() != PENDING) reasons.add(m.status()==RELEASED ? "ALREADY_RELEASED" : "NOT_PENDING");
        if (!m.passed()) reasons.add("NOT_PASSED");
        Certificate cert = certRepo.findByIdForUpdate(m.certificateId()).orElseThrow(...); // should exist
        if (cert.revoked()) reasons.add("CERTIFICATE_REVOKED");
        if (m.submittedBy().equals(actor)) reasons.add("SAME_ACTOR");
        if (!reasons.isEmpty()) failures.add(new ItemFailure(key, reasons));
        else toRelease.add(m);
    }
    if (!failures.isEmpty()) throw new BatchRejectedException(failures);
